"""Two-message check of the app's Responses request with the provider's web
search, against OpenAI and OpenRouter. Keys come from the app's conf and are
never printed. Writes each response's output item types and the replies."""
import json, sys, urllib.request, pathlib
W = pathlib.Path("/Users/kenneth/Projects/JusPrin/.claude/worktrees/web-search")
conf = json.load(open("/Users/kenneth/Library/Application Support/JusPrin2/JusPrin2.conf"))["jusprin_agent"]
TOOLS = json.loads((W / "tests/printer_prompt/printer_tools.json").read_text())
src = (W / "src/slic3r/GUI/JusPrin/AgentUI/src/printerInstructions.ts").read_text()
start = src.index("export const LOOK_IT_UP =")
look = "".join(json.loads('"' + p.replace("\\'", "'") + '"') for p in __import__("re").findall(r"'((?:[^'\\]|\\.)*)'", src[start:src.index(";", start)]))
INSTRUCTIONS = "You are JusPrin's printer assistant, helping someone connect their printer. Use plain language, one to three short sentences.\n" + look
PATHS = {
    "openai": ("https://api.openai.com/v1/responses", conf["openai_api_key"], "gpt-5.4-mini", {"type": "web_search"}),
    "openrouter": ("https://openrouter.ai/api/v1/responses", conf["openrouter_api_key"], "deepseek/deepseek-v4-flash", {"type": "openrouter:web_search"}),
}
def post(url, key, body):
    req = urllib.request.Request(url, data=json.dumps(body).encode(), method="POST",
        headers={"Authorization": "Bearer " + key, "Content-Type": "application/json", "X-Title": "JusPrin"})
    try:
        with urllib.request.urlopen(req, timeout=180) as r:
            completed = None
            for line in r:
                line = line.decode().strip()
                if line.startswith("data:"):
                    data = line[5:].strip()
                    if data and data != "[DONE]":
                        ev = json.loads(data)
                        if ev.get("type") in ("response.completed", "response.failed", "response.incomplete", "error"):
                            completed = ev
            return completed
    except urllib.error.HTTPError as e:
        return {"type": "http_error", "status": e.code, "body": e.read().decode(errors="replace")[:800]}
name = sys.argv[1]
url, key, model, search = PATHS[name]
user1 = {"role": "user", "content": [{"type": "input_text", "text": "I have a Bambu Lab P1S. Where do I turn on LAN Only mode on its screen?"}]}
user2 = {"role": "user", "content": [{"type": "input_text", "text": "Thanks. Is the access code on the same screen?"}]}
items = [user1]
for n, user in enumerate((None, user2), 1):
    if user: items.append(user)
    body = {"model": model, "store": False, "stream": True, "parallel_tool_calls": True,
            "instructions": INSTRUCTIONS, "tools": TOOLS + [search], "input": items}
    ev = post(url, key, body)
    if ev is None or ev.get("type") != "response.completed":
        print(f"{name} message {n}: NOT COMPLETED: {json.dumps(ev)[:900]}"); break
    out = ev["response"]["output"]
    texts = [c.get("text", "") for i in out if i.get("type") == "message" for c in i.get("content", []) if c.get("type") == "output_text"]
    usage = ev["response"].get("usage", {})
    print(f"{name} message {n}: completed; items {[i.get('type') for i in out]}; usage {json.dumps({k: usage.get(k) for k in ('input_tokens','output_tokens','server_tool_use_details','cost') if k in usage})}")
    print("  reply:", " ".join(texts)[:600].replace("\n", " "))
    items += out
EOF
